const test=require('node:test'),assert=require('node:assert/strict');
test('terrain relief retains the existing default and scales the same shared surface deterministically',async()=>{const {rawTerrain,boardHeight}=await import('../board-terrain.js');for(const [x,z]of [[0,0],[125,-210],[-300,170]]){assert.equal(rawTerrain(x,z,41,0),0);assert(Math.abs(rawTerrain(x,z,41,.35)-rawTerrain(x,z,41)*.35)<1e-10);assert.notEqual(rawTerrain(x,z,41),rawTerrain(x,z,73));const h=boardHeight({plans:[]},73,{relief:.35});assert.equal(h(x,z),rawTerrain(x,z,73,.35));}});
test('terrain settings survive board edits and undo without changing tile dimensions',async()=>{const {emptyBoard}=await import('../playground-model.js');const {compositionHistory}=await import('../board-state.js');const {TILE_METRICS}=await import('../tile-metrics.js');const initial=emptyBoard('terrain-test'),history=compositionHistory(initial),metrics=JSON.stringify(TILE_METRICS);history.commit({...initial,revision:1,terrain:{seed:73,relief:.35}});let undo=history.peek('undo');assert.equal(undo.terrain,undefined);history.accept('undo',undo);const redo=history.peek('redo');assert.deepEqual(redo.terrain,{seed:73,relief:.35});assert.equal(JSON.stringify(TILE_METRICS),metrics);});
